const state = { language: "ar" };
const root = document.documentElement;
const heroPoster = document.querySelector("#hero-poster");
const languageButtons = document.querySelectorAll("[data-language]");
const menuToggle = document.querySelector(".menu-toggle");
const navigation = document.querySelector(".primary-nav");
const form = document.querySelector("#reservation-form");
const status = document.querySelector("#form-status");

function applyLanguage(language) {
  const copy = translations[language] || translations.ar;
  state.language = language;
  root.lang = language;
  root.dir = language === "ar" ? "rtl" : "ltr";
  document.title = language === "ar" ? "رحلة الراحة | حجز فنادق مكة" : language === "tr" ? "Rihlat Al Raha | Mekke Otelleri" : "Rihlat Al Raha | Makkah Hotels";

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    if (copy[key]) element.textContent = copy[key];
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => {
    const key = element.dataset.i18nPlaceholder;
    if (copy[key]) element.placeholder = copy[key];
  });
  document.querySelectorAll("[data-languages]").forEach((element) => {
    element.hidden = !element.dataset.languages.split(",").includes(language);
  });
  languageButtons.forEach((button) => {
    const active = button.dataset.language === language;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  heroPoster.src = language === "tr" ? "./assets/promo_tyr.jpeg" : "./assets/promo.jpeg";
  heroPoster.alt = language === "tr" ? "Rafahya Al Karam Hotel Eylül kampanyası" : language === "en" ? "Arabic National Day hotel offer" : "عرض اليوم الوطني لفندق فيرتا المحبس";
  localStorage.setItem("rihlat-language", language);
}

languageButtons.forEach((button) => button.addEventListener("click", () => applyLanguage(button.dataset.language)));

menuToggle.addEventListener("click", () => {
  const open = navigation.classList.toggle("open");
  menuToggle.setAttribute("aria-expanded", String(open));
  document.body.classList.toggle("menu-open", open);
});

navigation.querySelectorAll("a").forEach((link) => link.addEventListener("click", () => {
  navigation.classList.remove("open");
  menuToggle.setAttribute("aria-expanded", "false");
  document.body.classList.remove("menu-open");
}));

document.querySelectorAll(".choose-hotel").forEach((button) => button.addEventListener("click", () => {
  form.elements.hotel.value = button.dataset.hotel;
  document.querySelector("#reservation").scrollIntoView({ behavior: "smooth" });
  window.setTimeout(() => form.elements.arrival.focus(), 450);
}));

const today = new Date().toISOString().split("T")[0];
form.elements.arrival.min = today;
form.elements.departure.min = today;
form.elements.arrival.addEventListener("change", () => {
  form.elements.departure.min = form.elements.arrival.value || today;
  if (form.elements.departure.value && form.elements.departure.value <= form.elements.arrival.value) form.elements.departure.value = "";
});

function hotelName(value, language) {
  if (value === "verta") return translations[language].vertaName;
  if (value === "rafahya") return translations[language].rafahyaName;
  return value;
}

function validateForm() {
  let valid = true;
  form.querySelectorAll("[required]").forEach((field) => {
    const fieldValid = field.checkValidity();
    field.setAttribute("aria-invalid", String(!fieldValid));
    if (!fieldValid) valid = false;
  });
  if (form.elements.arrival.value && form.elements.departure.value && form.elements.departure.value <= form.elements.arrival.value) {
    form.elements.departure.setAttribute("aria-invalid", "true");
    valid = false;
  }
  return valid;
}

function buildWhatsAppMessage(values, language) {
  const hotel = hotelName(values.get("hotel"), language);
  if (language === "tr") return `Merhaba, otel rezervasyonu hakkında bilgi almak istiyorum.\n\nOtel: ${hotel}\nGiriş: ${values.get("arrival")}\nÇıkış: ${values.get("departure")}\nOda: ${values.get("rooms")}\nKişi: ${values.get("guests")}\nAd soyad: ${values.get("name")}\nTelefon: ${values.get("phone")}\nNot: ${values.get("notes") || "-"}`;
  if (language === "en") return `Hello, I would like to request a hotel reservation.\n\nHotel: ${hotel}\nArrival: ${values.get("arrival")}\nDeparture: ${values.get("departure")}\nRooms: ${values.get("rooms")}\nGuests: ${values.get("guests")}\nName: ${values.get("name")}\nPhone: ${values.get("phone")}\nNotes: ${values.get("notes") || "-"}`;
  return `السلام عليكم، أرغب في الاستفسار عن حجز فندق.\n\nالفندق: ${hotel}\nتاريخ الوصول: ${values.get("arrival")}\nتاريخ المغادرة: ${values.get("departure")}\nعدد الغرف: ${values.get("rooms")}\nعدد الأشخاص: ${values.get("guests")}\nالاسم: ${values.get("name")}\nرقم الهاتف: ${values.get("phone")}\nملاحظات: ${values.get("notes") || "-"}`;
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  status.textContent = "";
  if (!validateForm()) {
    status.textContent = translations[state.language].formError;
    form.querySelector('[aria-invalid="true"]')?.focus();
    return;
  }
  const message = buildWhatsAppMessage(new FormData(form), state.language);
  window.open(`https://wa.me/966509530219?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer");
});

function registerWebMcpTool() {
  const context = document.modelContext;
  if (!context?.registerTool) return;
  const lifecycle = new AbortController();
  try {
    Promise.resolve(context.registerTool({
      name: "prepare_reservation_request",
      title: "Prepare hotel reservation request",
      description: "Fill the visible Rihlat Al Raha reservation form with a guest's hotel and stay details. This stages the request but does not send it.",
      inputSchema: {
        type: "object",
        properties: {
          hotel: { type: "string", enum: ["verta", "rafahya"] },
          arrival: { type: "string", format: "date" },
          departure: { type: "string", format: "date" },
          rooms: { type: "integer", minimum: 1 },
          guests: { type: "integer", minimum: 1 },
          name: { type: "string" },
          phone: { type: "string" },
          notes: { type: "string" }
        },
        required: ["hotel", "arrival", "departure", "rooms", "guests", "name", "phone"],
        additionalProperties: false
      },
      annotations: { readOnlyHint: false, untrustedContentHint: false },
      execute(input) {
        if (!input || !["verta", "rafahya"].includes(input.hotel) || input.departure <= input.arrival || input.rooms < 1 || input.guests < 1) throw new Error("Invalid reservation details");
        Object.entries(input).forEach(([key, value]) => { if (form.elements[key]) form.elements[key].value = String(value); });
        document.querySelector("#reservation").scrollIntoView({ behavior: "smooth" });
        return { status: "staged", hotel: input.hotel, arrival: input.arrival, departure: input.departure };
      }
    }, { signal: lifecycle.signal })).catch(() => {});
  } catch (_) {}
}

document.querySelector("#year").textContent = String(new Date().getFullYear());
applyLanguage(localStorage.getItem("rihlat-language") || "ar");
registerWebMcpTool();
